import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BGlkWkwp.js";const m=JSON.parse('{"title":"Presence","description":"","frontmatter":{},"headers":[],"relativePath":"components/presence.md","filePath":"components/presence.md"}'),n={name:"components/presence.md"};function s(d,e,c,i,h,l){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="presence" tabindex="-1">Presence <a class="header-anchor" href="#presence" aria-label="Permalink to &quot;Presence&quot;">​</a></h1><p>Presence shows the people who are here now, as overlapping avatars, or the roster of everyone.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it in a toolbar of a shared document; one person is an <a href="./avatar">Avatar</a>, and the people of a comment on the stage are a <a href="./pin">Pin</a>. <code>max</code> sets how many avatars show; the others gather as &quot;+n&quot;, so that many people never widen it, and &quot;+n&quot; opens the roster. <code>roster</code> renders the list of everyone instead (name, &quot;(you)&quot; and role), for a menu or a panel that holds it. Each person has an <code>id</code> when names can repeat (the same person in two places).</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>users</code></td><td>required</td><td>The people (below)</td></tr><tr><td><code>max</code></td><td><code>3</code></td><td>How many avatars show before &quot;+n&quot;</td></tr><tr><td><code>roster</code></td><td><code>false</code></td><td>Renders the roster only</td></tr></tbody></table><p>Each person has <code>name</code>, and optionally <code>id</code> (a unique key; without it the position in the list), <code>color</code> (the surface of their avatar), <code>role</code> (<code>edit</code> or <code>view</code>) and <code>you</code>.</p><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The avatars are circles of a small button that overlap by gap-xs, each with a ring two lines wide in the panel color; the one under the pointer comes to the front. A person&#39;s color is the surface of their avatar, without one the fill color; the contrast of a color is the application&#39;s. &quot;+n&quot; is a button that looks like an avatar and opens the roster in a <a href="./dropdown">Dropdown</a>: the width of a popover, the panel surface and a strong line. The initials are the first two letters of a Latin name, otherwise its first character. With <code>roster</code> it has no container of its own: a caption with the count and, with more than eight people, a search, in a Block, then the people as list items with a line between them, a small avatar and a badge of the role; eight items show and more scroll. The words come from the messages <code>participants</code>, <code>showMore</code>, <code>searchByName</code>, <code>searchParticipants</code>, <code>noParticipants</code>, <code>you</code>, <code>roleEditor</code> and <code>roleViewer</code>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/presence/" title="Presence" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/presence/" target="_blank" rel="noopener">Presence</a></figcaption></figure>',11)])])}const u=t(n,[["render",s]]);export{m as __pageData,u as default};
